import 'package:zan/Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';import '../Models/get_all_services_model.dart';class  CarpenterServicesSources { static Future<List<GetAllServicesModel>> getAllServices()async{  final response = await DioHelper.getData(path:ApiEndpoints.allCarpentryServices ) ;  return (response.data["data"]["services"] as List).map((e) => GetAllServicesModel.fromJson(e)).toList();}}